interface Level {
    int score();
    default String label() {
        return score() >= 60 ? "PASS" : "FAIL";
    }
}

record Result(int score) implements Level {
    String grade() {
        return switch (score / 10) {
            case 10, 9 -> "A";
            case 8 -> "B";
            default -> "C";
        };
    }
}

public class Main {
    public static void main(String[] args) {
        Level x = new Result(85);
        Result r = (Result) x;
        System.out.print(x.label() + ":" + r.grade());
    }
}

class ReadException extends Exception { }

class Base {
