interface Named {
    default String name() { return "N"; }
}

class Base {
    static int count = 0;
    final int id;

    Base() {
        id = ++count;
    }

    String name() { return "B" + id; }
}

class Child extends Base implements Named {
    @Override
    public String name() {
        return super.name() + "C";
    }
}

public class Main {
    public static void main(String[] args) {
        Base a = new Child();
        Base b = new Child();

        Object x = b;
        if (x instanceof Child c && c.id == 2) {
            System.out.print(a.name() + ":" + c.name() + ":" + Base.count);
        }
    }
}
